7: namespace QBrainAi.Repl.Core;
8: 
9: /// <summary>
10: /// TR-MCP-REPL-001 AC-002: parses a configured REPL command timeout. A whole number of seconds from 1 to
11: /// <see cref="LargestSeconds"/>, the largest delay <see cref="CancellationTokenSource.CancelAfter(TimeSpan)"/> accepts,
12: /// is used; any other value (unset, empty, not a number, zero, negative or larger) gives <see cref="Default"/>.
13: /// </summary>
14: internal static class ReplCommandTimeout
15: {
16:     /// <summary>The timeout that applies when no valid value is configured.</summary>
17:     internal static readonly TimeSpan Default = TimeSpan.FromMinutes(2);
18: 
19:     /// <summary>
20:     /// The largest whole number of seconds the cancellation timer accepts: its limit is 4294967294 milliseconds.
21:     /// </summary>
22:     internal const long LargestSeconds = 4294967;
23: 
24:     /// <summary>Parses a configured value into the timeout that applies.</summary>
25:     /// <param name="configured">The configured value, or null when the variable is unset.</param>
26:     /// <returns>The configured timeout when it is valid; otherwise <see cref="Default"/>.</returns>
27:     internal static TimeSpan Parse(string? configured) =>
28:         long.TryParse(configured, NumberStyles.Integer, CultureInfo.InvariantCulture, out var seconds) && seconds is >= 1 and <= LargestSeconds
29:             ? TimeSpan.FromSeconds(seconds)
30:             : Default;
31: 
32:     /// <summary>Reads the variable that configures a timeout once and parses it; both call sites use this.</summary>
33:     /// <param name="readVariable">Reads one environment variable by name; the call sites default to the process environment.</param>
34:     /// <param name="variableName">The variable that configures the timeout.</param>
35:     /// <returns>The timeout that applies.</returns>
36:     internal static TimeSpan Read(Func<string, string?> readVariable, string variableName)
37:     {
38:         ArgumentNullException.ThrowIfNull(readVariable);
39:         return Parse(readVariable(variableName));
40:     }
41: }
