87:     /// mount-point tag, a substitute name without the \??\ prefix, a print name that starts without the null after the
88:     /// substitute name, and a data length that also counts the 8-byte header.
89:     /// </summary>
90:     [Fact]
91:     public void WrongBuilders_AreRejectedInsidePassingHarness()
92:     {
93:         Assert.NotNull(Record.Exception(() => AssertBufferContract(target => Scripted(target, 0xA000000C, @"\??\", nullGap: true, headerInLength: false))));
94:         Assert.NotNull(Record.Exception(() => AssertBufferContract(target => Scripted(target, MountPointTag, string.Empty, nullGap: true, headerInLength: false))));
95:         Assert.NotNull(Record.Exception(() => AssertBufferContract(target => Scripted(target, MountPointTag, @"\??\", nullGap: false, headerInLength: false))));
96:         Assert.NotNull(Record.Exception(() => AssertBufferContract(target => Scripted(target, MountPointTag, @"\??\", nullGap: true, headerInLength: true))));
97:     }
98: 
99:     private static byte[] Scripted(string target, uint tag, string prefix, bool nullGap, bool headerInLength)
100:     {
101:         var substitute = Encoding.Unicode.GetBytes(prefix + target);
102:         var print = Encoding.Unicode.GetBytes(target);
103:         var gap = nullGap ? 2 : 0;
104:         var pathLength = substitute.Length + gap + print.Length + 2;
105:         var buffer = new byte[16 + pathLength];
106:         BinaryPrimitives.WriteUInt32LittleEndian(buffer.AsSpan(0, 4), tag);
107:         BinaryPrimitives.WriteUInt16LittleEndian(buffer.AsSpan(4, 2), (ushort)(8 + pathLength + (headerInLength ? 8 : 0)));
108:         BinaryPrimitives.WriteUInt16LittleEndian(buffer.AsSpan(10, 2), (ushort)substitute.Length);
109:         BinaryPrimitives.WriteUInt16LittleEndian(buffer.AsSpan(12, 2), (ushort)(substitute.Length + gap));
110:         BinaryPrimitives.WriteUInt16LittleEndian(buffer.AsSpan(14, 2), (ushort)print.Length);
111:         substitute.CopyTo(buffer, 16);
112:         print.CopyTo(buffer, 16 + substitute.Length + gap);
113:         return buffer;
114:     }
115: }
