135:             throw new PlatformNotSupportedException("This integration test runs only in the Windows lane.");
136:         var root = Path.Combine(Path.GetTempPath(), "mcp-junction-" + Guid.NewGuid().ToString("N"));
137:         var target = Path.Combine(root, "target");
138:         var alias = Path.Combine(root, "alias");
139:         Directory.CreateDirectory(target);
140:         File.WriteAllText(Path.Combine(target, "document.md"), "through the junction");
141:         try
142:         {
143:             WindowsJunction.Create(alias, target);
144: 
145:             var info = new DirectoryInfo(alias);
146:             Assert.True(info.Attributes.HasFlag(FileAttributes.ReparsePoint));
147:             Assert.Equal(Path.GetFullPath(target), Path.GetFullPath(Assert.IsType<string>(info.LinkTarget)));
148:             Assert.Equal("through the junction", File.ReadAllText(Path.Combine(alias, "document.md")));
149:         }
150:         finally
151:         {
152:             if (Directory.Exists(alias))
153:                 Directory.Delete(alias);
154:             Directory.Delete(root, recursive: true);
155:         }
156:     }
157: }
