289: +using System.Data.Common;
290: +using System.Diagnostics;
291: +using System.Globalization;
292: +using System.Net.Sockets;
293: +
294: +/// <summary>
295: +/// TR-MCP-NUKE-018: Production Linux provisioning of the provider test endpoints (operator decision 2026-10-11,
296: +/// BUG-BASELINE-005). Each variable already set is adopted; otherwise it is loaded from the test-database env file and
297: +/// its dedicated qbrain-test container is started when stopped. Every endpoint must accept TCP before tests run.
298: +/// Actions and errors name variables, the file, containers and host:port only, never connection-string values.
299: +/// </summary>
300: +sealed class LinuxProviderTestProvisioner : IProviderTestProvisioner
301: +{
302: +    private static readonly TimeSpan ProbeTimeout = TimeSpan.FromSeconds(2);
303: +    private const int ProbeAttempts = 30;
304: +
305: +    private static readonly (string Variable, string Container, int DefaultPort, bool IsSqlServer)[] Endpoints =
306: +    [
307: +        (ProviderTestNames.PostgresVariable, ProviderTestNames.PostgresContainer, 5432, false),
308: +        (ProviderTestNames.SqlServerVariable, ProviderTestNames.SqlServerContainer, 1433, true),
309: +    ];
310: +
311: +    /// <inheritdoc />
312: +    public ProviderTestProvisioningResult Provision(string envFilePath, IProviderTestHost host)
313: +    {
314: +        ArgumentException.ThrowIfNullOrWhiteSpace(envFilePath);
315: +        ArgumentNullException.ThrowIfNull(host);
316: +        var actions = new List<string>();
317: +        var errors = new List<string>();
318: +        Dictionary<string, string>? fileValues = null;
319: +        var fileMissing = false;
320: +
321: +        foreach (var (variable, container, defaultPort, isSqlServer) in Endpoints)
322: +        {
323: +            var value = host.GetVariable(variable);
324: +            var loadedFromFile = false;
325: +            if (!string.IsNullOrWhiteSpace(value))
326: +            {
327: +                actions.Add("adopt " + variable + " (already set)");
328: +            }
329: +            else
330: +            {
331: +                if (fileValues is null && !fileMissing)
332: +                {
333: +                    var text = host.ReadFile(envFilePath);
334: +                    if (text is null)
335: +                    {
336: +                        fileMissing = true;
337: +                        errors.Add("test-database env file not found: " + envFilePath);
338: +                    }
339: +                    else
340: +                    {
341: +                        fileValues = ParseEnvFile(text);
342: +                    }
343: +                }
344: +
345: +                if (fileMissing)
346: +                {
347: +                    continue;
348: +                }
349: +
350: +                if (!fileValues!.TryGetValue(variable, out value) || string.IsNullOrWhiteSpace(value))
351: +                {
352: +                    errors.Add(variable + " is not defined in " + envFilePath);
353: +                    continue;
354: +                }
355: +
356: +                host.SetVariable(variable, value);
357: +                actions.Add("load " + variable + " from " + envFilePath);
358: +                loadedFromFile = true;
359: +            }
360: +
361: +            var startedNow = false;
362: +            if (loadedFromFile)
363: +            {
364: +                var state = host.GetContainerState(container);
365: +                if (state == ProviderTestContainerState.Missing)
366: +                {
367: +                    errors.Add("container " + container + " not found");
368: +                    continue;
369: +                }
370: +
371: +                if (state == ProviderTestContainerState.Stopped)
372: +                {
373: +                    if (!host.StartContainer(container))
374: +                    {
375: +                        errors.Add("container " + container + " could not be started");
376: +                        continue;
377: +                    }
378: +
379: +                    actions.Add("start " + container);
380: +                    startedNow = true;
381: +                }
382: +            }
383: +
384: +            if (!TryReadEndpoint(value, isSqlServer, defaultPort, out var endpointHost, out var port, out var problem))
385: +            {
386: +                errors.Add(variable + " " + problem);
387: +                continue;
388: +            }
389: +
390: +            var endpoint = endpointHost + ":" + port.ToString(CultureInfo.InvariantCulture);
391: +            var attempts = startedNow ? ProbeAttempts : 1;
392: +            var reachable = false;
393: +            for (var attempt = 0; attempt < attempts && !reachable; attempt++)
394: +            {
395: +                reachable = host.CanConnect(endpointHost, port, ProbeTimeout);
396: +                if (!reachable && attempt + 1 < attempts)
397: +                {
398: +                    Thread.Sleep(TimeSpan.FromSeconds(1));
399: +                }
400: +            }
401: +
402: +            if (reachable)
403: +            {
404: +                actions.Add("endpoint " + endpoint + " reachable");
405: +            }
406: +            else
407: +            {
408: +                errors.Add("endpoint " + endpoint + " for " + variable + " is not accepting connections");
409: +            }
410: +        }
411: +
412: +        return new ProviderTestProvisioningResult(actions, errors);
413: +    }
414: +
415: +    /// <summary>Parses KEY=VALUE lines; skips blanks and comments; strips an export prefix and matching quotes.</summary>
416: +    internal static Dictionary<string, string> ParseEnvFile(string text)
417: +    {
418: +        var values = new Dictionary<string, string>(StringComparer.Ordinal);
419: +        foreach (var raw in text.Split('\n'))
420: +        {
421: +            var line = raw.Trim();
422: +            if (line.Length == 0 || line.StartsWith('#'))
423: +            {
424: +                continue;
425: +            }
426: +
427: +            if (line.StartsWith("export ", StringComparison.Ordinal))
428: +            {
429: +                line = line["export ".Length..].TrimStart();
430: +            }
431: +
432: +            var equals = line.IndexOf('=', StringComparison.Ordinal);
433: +            if (equals <= 0)
434: +            {
435: +                continue;
436: +            }
437: +
438: +            var key = line[..equals].Trim();
439: +            var value = line[(equals + 1)..].Trim();
440: +            if (value.Length >= 2 && (value[0] == '"' || value[0] == '\'') && value[^1] == value[0])
441: +            {
442: +                value = value[1..^1];
443: +            }
444: +
445: +            values[key] = value;
446: +        }
447: +
448: +        return values;
449: +    }
450: +
451: +    private static bool TryReadEndpoint(string connectionString, bool isSqlServer, int defaultPort, out string host, out int port, out string problem)
452: +    {
453: +        host = string.Empty;
454: +        port = defaultPort;
455: +        problem = string.Empty;
456: +        var builder = new DbConnectionStringBuilder();
457: +        try
458: +        {
459: +            builder.ConnectionString = connectionString;
460: +        }
461: +        catch (ArgumentException)
462: +        {
463: +            problem = "is not a valid connection string";
464: +            return false;
465: +        }
466: +
467: +        if (isSqlServer)
468: +        {
469: +            var server = FirstValue(builder, "Server", "Data Source", "Address", "Addr", "Network Address");
470: +            if (server is null)
471: +            {
472: +                problem = "names no server";
473: +                return false;
474: +            }
475: +
476: +            if (server.StartsWith("(localdb)", StringComparison.OrdinalIgnoreCase))
477: +            {
478: +                problem = "names a LocalDB server, which has no TCP endpoint on Linux";
479: +                return false;
480: +            }
481: +
482: +            if (server.StartsWith("tcp:", StringComparison.OrdinalIgnoreCase))
483: +            {
484: +                server = server[4..];
485: +            }
486: +
487: +            var comma = server.IndexOf(',', StringComparison.Ordinal);
488: +            if (comma >= 0)
489: +            {
490: +                if (!int.TryParse(server[(comma + 1)..].Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out port))
491: +                {
492: +                    problem = "names a server with an unreadable port";
493: +                    return false;
494: +                }
495: +
496: +                server = server[..comma];
497: +            }
498: +
499: +            host = server.Split('\\')[0].Trim();
500: +        }
501: +        else
502: +        {
503: +            var server = FirstValue(builder, "Host", "Server");
504: +            if (server is null)
505: +            {
506: +                problem = "names no host";
507: +                return false;
508: +            }
