48:     /// <param name="body">The test body; it receives the test folder and the fallback folder.</param>
49:     /// <returns>A task that completes when the body has run and the variables are restored.</returns>
50:     internal static async Task RunWithTestFoldersAsync(string primaryName, Func<string, string, Task> body)
51:     {
52:         ArgumentNullException.ThrowIfNull(body);
53:         if (!Names.Contains(primaryName, StringComparer.Ordinal))
54:             throw new ArgumentException($"{primaryName} is not a CLI temp variable name.", nameof(primaryName));
