12: /// Requirement coverage: TR-MCP-NUKE-019 AC-2 (every integration case runs and passes in its host's lane at
13: /// 0 failed). Found by the Windows interactive lane ug-r3-win-lane-2, where
14: /// SqlServerAuditPayloadMigrationTests failed after the 15 s default connect timeout; fix chosen by the operator on
15: /// 2026-10-20 ("Fix the flake in PR 87 (Recommended)"). Test data: scripted connection strings parsed with
16: /// <see cref="SqlConnectionStringBuilder"/>; no server is contacted and no environment variable is read. Negative
17: /// controls feed the default assertion the literal the three classes used before (15 s default), a short timeout,
18: /// another server, a string without the trusted certificate, and one that names a database, and prove it rejects each.
19: /// </remarks>
20: public sealed class SqlServerTestConnectionTests
21: {
22:     private const string RequiredDefault =
23:         "Server=(localdb)\\MSSQLLocalDB;Integrated Security=True;TrustServerCertificate=True;Connect Timeout=120";
24: 
25:     /// <summary>
26:     /// Asserts that <paramref name="connectionString"/> is the required default: LocalDB, integrated security, a
27:     /// trusted server certificate, no database, and a 120 s connect timeout.
28:     /// </summary>
29:     private static void AssertLocalDbDefault(string connectionString)
30:     {
31:         var builder = new SqlConnectionStringBuilder(connectionString);
32:         Assert.Equal(@"(localdb)\MSSQLLocalDB", builder.DataSource);
33:         Assert.True(builder.IntegratedSecurity);
34:         Assert.True(builder.TrustServerCertificate);
35:         Assert.Equal(string.Empty, builder.InitialCatalog);
