120:     /// <summary>
121:     /// Asserts one walk result against a case: the yielded directories, the yielded files, and the directories
122:     /// the walk listed, each compared as an ordinal set (the acceptance criteria fix membership, not order).
123:     /// </summary>
124:     private static void AssertWalk(
125:         (string[] Directories, string[] Files, string[] Listed) expected,
126:         IEnumerable<string> directories,
127:         IEnumerable<string> files,
128:         IEnumerable<string> listed)
129:     {
130:         Assert.Equal(expected.Directories.Order(StringComparer.Ordinal), directories.Order(StringComparer.Ordinal));
131:         Assert.Equal(expected.Files.Order(StringComparer.Ordinal), files.Order(StringComparer.Ordinal));
132:         Assert.Equal(
133:             expected.Listed.Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal),
134:             listed.Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal));
135:     }
