137:     /// <summary>Runs one walk over a fresh copy of a case's tree and asserts its result.</summary>
138:     private static void RunAndAssert(string name, WalkFunction walk)
139:     {
140:         var (treeFactory, root, directories, files, listed) = Cases[name];
141:         var tree = treeFactory();
142:         var result = walk(tree.List, root);
143:         AssertWalk((directories, files, listed), result.Directories, result.Files, tree.Listed);
144:     }
